"""
jsonable_encoder converts a Python object to a JSON-friendly dict
(e.g. datetimes to strings, Pydantic models to dicts).

Taken from FastAPI, and made a bit simpler
https://github.com/tiangolo/fastapi/blob/master/fastapi/encoders.py
"""

import base64
import dataclasses
import datetime as dt
from enum import Enum
from pathlib import PurePath
from types import GeneratorType
from typing import Any, Callable, Dict, List, Optional, Set, Union

import pydantic
from .datetime_utils import serialize_datetime
from .pydantic_utilities import (
    IS_PYDANTIC_V2,
    encode_by_type,
    to_jsonable_with_fallback,
)

SetIntStr = Set[Union[int, str]]
DictIntStrAny = Dict[Union[int, str], Any]


def jsonable_encoder(obj: Any, custom_encoder: Optional[Dict[Any, Callable[[Any], Any]]] = None) -> Any:
    custom_encoder = custom_encoder or {}

    # Fast-exit for most common/cheap types
    if isinstance(obj, (str, int, float, type(None))):
        return obj
    if isinstance(obj, bytes):
        return base64.b64encode(obj).decode("utf-8")
    if isinstance(obj, Enum):
        return obj.value
    if isinstance(obj, PurePath):
        return str(obj)
    if isinstance(obj, dt.datetime):
        return serialize_datetime(obj)
    if isinstance(obj, dt.date):
        return str(obj)
    if dataclasses.is_dataclass(obj):
        return jsonable_encoder(dataclasses.asdict(obj), custom_encoder=custom_encoder)

    # Custom encoders: check type and isinstance in cheap order
    if custom_encoder:
        obj_type = type(obj)
        if obj_type in custom_encoder:
            return custom_encoder[obj_type](obj)
        for encoder_type, encoder_instance in custom_encoder.items():
            if isinstance(obj, encoder_type):
                return encoder_instance(obj)

    if isinstance(obj, pydantic.BaseModel):
        if IS_PYDANTIC_V2:
            encoder = getattr(obj.model_config, "json_encoders", {})  # type: ignore # Pydantic v2
        else:
            encoder = getattr(obj.__config__, "json_encoders", {})  # type: ignore # Pydantic v1
        if custom_encoder:
            # Avoid mutating the shared encoder dict
            encoder = dict(encoder)
            encoder.update(custom_encoder)
        obj_dict = obj.dict(by_alias=True)
        # Only consider root extraction if those are the only keys (avoid false root extraction)
        if "__root__" in obj_dict and len(obj_dict) == 1:
            obj_dict = obj_dict["__root__"]
        elif "root" in obj_dict and len(obj_dict) == 1:
            obj_dict = obj_dict["root"]
        return jsonable_encoder(obj_dict, custom_encoder=encoder)
    if isinstance(obj, dict):
        # No need to make allowed_keys set: .items() always iterates keys available
        return {
            jsonable_encoder(key, custom_encoder=custom_encoder):
            jsonable_encoder(value, custom_encoder=custom_encoder)
            for key, value in obj.items()
        }

    if isinstance(obj, (list, set, frozenset, GeneratorType, tuple)):
        # Use list comprehension for better performance
        return [
            jsonable_encoder(item, custom_encoder=custom_encoder) for item in obj
        ]

    # Fallback serializer as defined in-place for slight performance gain

    def fallback_serializer(o: Any) -> Any:
        attempt_encode = encode_by_type(o)
        if attempt_encode is not None:
            return attempt_encode

        try:
            data = dict(o)
        except Exception as e:
            errors: List[Exception] = [e]
            try:
                data = vars(o)
            except Exception as e2:
                errors.append(e2)
                raise ValueError(errors) from e2
        return jsonable_encoder(data, custom_encoder=custom_encoder)

    return to_jsonable_with_fallback(obj, fallback_serializer)
